mapper.update:
UPDATE cs_pending_handoff
SET status = 'RESULT_UNKNOWN', failure_type = #{failureType},
    attempt_count = attempt_count + 1, next_attempt_at = #{now},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}
  AND version = #{expectedVersion}
  AND status IN ('PREPARED', 'RESULT_UNKNOWN')

UPDATE cs_pending_handoff
SET status = 'CONFIRMED', failure_type = 'NONE',
    attempt_count = attempt_count + 1, next_attempt_at = 0,
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}
  AND status NOT IN ('CONFIRMED', 'MANUALLY_CLOSED')

UPDATE cs_pending_handoff
SET status = 'PROCESSING', next_attempt_at = #{leaseUntil},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}
  AND version = #{expectedVersion}
  AND status IN ('PREPARED', 'RESULT_UNKNOWN', 'RETRY_SCHEDULED', 'PROCESSING')
  AND next_attempt_at <= #{now}

UPDATE cs_pending_handoff
SET status = #{targetStatus}, failure_type = #{failureType},
    attempt_count = attempt_count + 1, next_attempt_at = #{nextAttemptAt},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}
  AND version = #{expectedVersion}
  AND status = 'PROCESSING'
  AND EXISTS (
      SELECT 1 FROM cs_pending_handoff_claim
      WHERE tenant_id = #{tenantId}
        AND idempotency_key = #{idempotencyKey}
        AND owner_token = #{ownerToken}
        AND lease_until = #{leaseUntil}
        AND lease_until > #{now}
  )

UPDATE cs_pending_handoff
SET status = 'NEEDS_MANUAL_REVIEW', failure_type = #{failureType},
    attempt_count = attempt_count + 1, next_attempt_at = #{nextAttemptAt},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND idempotency_key = #{idempotencyKey}
  AND status NOT IN ('CONFIRMED', 'MANUALLY_CLOSED')

mapper.select:
SELECT tenant_id, idempotency_key
FROM cs_pending_handoff
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}

SELECT tenant_id, idempotency_key
FROM cs_pending_handoff
WHERE tenant_id = #{tenantId}
AND


        (status = #{status} OR (
            status <> 'MANUALLY_CLOSED' AND EXISTS (
                SELECT 1 FROM cs_pending_handoff_result AS result_row
                WHERE result_row.tenant_id = cs_pending_handoff.tenant_id
                  AND result_row.idempotency_key = cs_pending_handoff.idempotency_key
            )
        ))


        status = #{status}


        status = #{status} AND NOT EXISTS (
            SELECT 1 FROM cs_pending_handoff_result AS result_row
            WHERE result_row.tenant_id = cs_pending_handoff.tenant_id
              AND result_row.idempotency_key = cs_pending_handoff.idempotency_key
        )



    AND (
        updated_at < #{cursorUpdatedAt}
        OR (updated_at = #{cursorUpdatedAt} AND outbox_id < #{cursorOutboxId})
    )

ORDER BY updated_at DESC, outbox_id DESC
LIMIT #{limit}

